def seed_missing_schemes(db: Session) -> None:
    """Insert only sample entries that do not exist; never overwrite stored records."""
    existing = set(db.scalars(select(Scheme.slug)).all())
    missing = [Scheme(**item) for item in SCHEMES if item["slug"] not in existing]
    if missing:
        db.add_all(missing)
        db.commit()
